namespace sfve::backdrop {

// Generated by CMakeLists.txt from data/menu-art.json (sfve_ember).
extern const char* const kEmbeddedMenuArtJson;

namespace {

constexpr size_t kLongestPath = 192;

bool NameChar(char c)
{
	return (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_';
}

// An object whose keys are all among `allowed` and include `required`: a
// hand-edited file with a misspelt key is refused rather than read without it.
bool Keys(const nlohmann::json& value, std::initializer_list<const char*> required, std::initializer_list<const char*> allowed)
{
	if (!value.is_object()) return false;
	for (const char* key : required) {
		if (!value.contains(key)) return false;
	}
	for (auto item = value.begin(); item != value.end(); ++item) {
		if (std::none_of(allowed.begin(), allowed.end(), [&item](const char* key) { return item.key() == key; })) return false;
	}
	return true;
}

float Clamp01(float value)
{
	return value < 0 ? 0 : value > 1 ? 1 : value;
}

} // namespace

bool ArtPathValid(std::string_view path)
{
	if (path.empty() || path.size() > kLongestPath) return false;
	int names = 0;
	size_t start = 0;
	while (start <= path.size()) {
		const size_t slash = std::min(path.find('/', start), path.size());
		if (slash == start) return false; // an empty name: a leading, trailing or doubled '/'
		for (size_t i = start; i < slash; i++) {
			if (!NameChar(path[i])) return false;
		}
		names++;
		start = slash + 1;
	}
	return names >= 2;
}

std::wstring ObjectPathOf(std::string_view path)
{
	if (!ArtPathValid(path)) return {};
	const size_t slash = path.rfind('/');
	const std::wstring folder(path.begin(), path.begin() + (std::ptrdiff_t)slash);
	const std::wstring name(path.begin() + (std::ptrdiff_t)slash + 1, path.end());
	return pictures::ObjectPath(folder, name);
}

bool ParseArtSet(std::string_view json, ArtSet& set, std::string& error)
{
	const nlohmann::json root = nlohmann::json::parse(json.begin(), json.end(), nullptr, false);
	if (root.is_discarded()) return error = "not JSON", false;
	if (!Keys(root, {"version", "families"}, {"version", "families"})) return error = "the top needs version and families, and nothing else", false;
	if (!root["version"].is_number_integer() || root["version"].get<long long>() != 1) return error = "version is not 1", false;
	if (!root["families"].is_array()) return error = "families is not a list", false;
	ArtSet parsed;
	std::set<std::string> names, paths;
	for (const nlohmann::json& entry : root["families"]) {
		if (!Keys(entry, {"name", "use", "paths"}, {"name", "use", "note", "paths"})) {
			return error = "a family needs name, use and paths (and may have a note), and nothing else", false;
		}
		if (!entry["name"].is_string() || entry["name"].get<std::string>().empty()) return error = "a family's name is not a word", false;
		Family family;
		family.name = entry["name"].get<std::string>();
		if (!names.insert(family.name).second) return error = "the family " + family.name + " is listed twice", false;
		if (!entry["use"].is_boolean()) return error = family.name + ": use is not true or false", false;
		family.use = entry["use"].get<bool>();
		if (entry.contains("note") && !entry["note"].is_string()) return error = family.name + ": its note is not text", false;
		if (!entry["paths"].is_array()) return error = family.name + ": paths is not a list", false;
		for (const nlohmann::json& path : entry["paths"]) {
			if (!path.is_string() || !ArtPathValid(path.get<std::string>())) {
				return error = family.name + ": " + (path.is_string() ? path.get<std::string>() : path.dump()) + " is not a path under /Game/", false;
			}
			if (!paths.insert(path.get<std::string>()).second) return error = path.get<std::string>() + " is listed twice", false;
			family.paths.push_back(path.get<std::string>());
		}
		parsed.families.push_back(std::move(family));
	}
	set = std::move(parsed);
	error.clear();
	return true;
}

const ArtSet& EmbeddedArtSet()
{
	static const ArtSet set = [] {
		ArtSet parsed;
		std::string error;
		if (!ParseArtSet(kEmbeddedMenuArtJson, parsed, error)) parsed = {};
		return parsed;
	}();
	return set;
}

std::vector<std::string> UsedPaths(const ArtSet& set)
{
	std::vector<std::string> paths;
	for (const Family& family : set.families) {
		if (family.use) paths.insert(paths.end(), family.paths.begin(), family.paths.end());
	}
	return paths;
}

std::vector<ListedPath> AllPaths(const ArtSet& set)
{
	std::vector<ListedPath> paths;
	for (const Family& family : set.families) {
		for (const std::string& path : family.paths) paths.push_back({family.name, path, family.use});
	}
	return paths;
}

PageKind PageKindOf(std::string_view screen)
{
	// Home's rows, Online play's and Training select's: a column on the left,
	// the screen open beside it.
	for (std::string_view column : {"home", "online", "training"}) {
		if (screen == column) return PageKind::Column;
	}
	return PageKind::Dense;
}

const char* PageKindName(PageKind kind)
{
	return kind == PageKind::Column ? "column" : "dense";
}

Scrim ScrimOf(PageKind kind)
{
	// A column: heaviest behind the rows on the left and the hint bar,
	// lightest at the top right, where the screen is open (the old static
	// backdrop's tint, a little heavier at the bottom right for the hint
	// bar's status). A dense page: even, a little heavier at the bottom.
	if (kind == PageKind::Column) return {0.93f, 0.60f, 0.77f, 0.96f};
	return {0.84f, 0.84f, 0.89f, 0.89f};
}

Scrim Mix(const Scrim& from, const Scrim& to, float t)
{
	t = Clamp01(t);
	const auto mix = [t](float a, float b) { return a + (b - a) * t; };
	return {mix(from.topLeft, to.topLeft), mix(from.topRight, to.topRight), mix(from.bottomRight, to.bottomRight),
		mix(from.bottomLeft, to.bottomLeft)};
}

float ScrimAt(const Scrim& scrim, float x, float y)
{
	x = Clamp01(x);
	y = Clamp01(y);
	const float top = scrim.topLeft + (scrim.topRight - scrim.topLeft) * x;
	const float bottom = scrim.bottomLeft + (scrim.bottomRight - scrim.bottomLeft) * x;
	return top + (bottom - top) * y;
}

UvRect CoverFit(int width, int height, float targetWidth, float targetHeight, float anchorX, float anchorY)
{
	UvRect uv;
	if (width <= 0 || height <= 0 || !(targetWidth > 0) || !(targetHeight > 0)) return uv;
	const float picture = (float)width / (float)height, target = targetWidth / targetHeight;
	if (target > picture) {
		// A wider screen: the picture's whole width, a band of its height.
		const float span = picture / target;
		uv.v0 = (1 - span) * Clamp01(anchorY);
		uv.v1 = uv.v0 + span;
	} else {
		// A narrower one (or the same shape): its whole height, a band of its width.
		const float span = target / picture;
		uv.u0 = (1 - span) * Clamp01(anchorX);
		uv.u1 = uv.u0 + span;
	}
	return uv;
}

float FadeCurve(float progress)
{
	const float t = Clamp01(progress);
	return t * t * (3 - 2 * t);
}

Cycle::Cycle(int entries, std::uint32_t seed, Timing timing)
	: entries_(entries > 0 ? entries : 0), timing_(timing), random_(seed), failed_((size_t)entries_, false)
{
	Refill();
}

int Cycle::Pick()
{
	// Through the shuffled order, a new shuffle each time it runs out; never
	// a failed picture, never the one shown, and never the one picked last
	// first in a new shuffle.
	for (int pass = 0; pass < 2; pass++) {
		while (cursor_ < order_.size()) {
			const int entry = order_[cursor_++];
			if (failed_[(size_t)entry] || entry == current_.entry) continue;
			lastPicked_ = entry;
			return entry;
		}
		order_.resize((size_t)entries_);
		for (int i = 0; i < entries_; i++) order_[(size_t)i] = i;
		std::shuffle(order_.begin(), order_.end(), random_);
		if (order_.size() > 1 && order_.front() == lastPicked_) {
			std::uniform_int_distribution<size_t> other(1, order_.size() - 1);
			std::swap(order_.front(), order_[other(random_)]);
		}
		cursor_ = 0;
	}
	return -1;
}

void Cycle::Refill()
{
	if (next_.entry >= 0 || fading_ || Exhausted()) return;
	next_ = {Pick(), false, false};
}

std::optional<int> Cycle::Wanted() const
{
	if (next_.entry < 0 || next_.loading || next_.ready || fading_ || stale_ >= 0) return std::nullopt;
	if (clock_ < settleUntil_ || clock_ < retryAt_) return std::nullopt;
	return next_.entry;
}

void Cycle::Started(int entry)
{
	if (entry == next_.entry && !next_.loading && !next_.ready) next_.loading = true;
}

bool Cycle::Loaded(int entry, bool ok)
{
	if (entry >= 0 && entry == stale_) {
		stale_ = -1;
		return false;
	}
	if (entry < 0 || entry != next_.entry || !next_.loading) return false;
	next_.loading = false;
	if (ok) {
		next_.ready = true;
		return true;
	}
	failed_[(size_t)entry] = true;
	failedCount_++;
	next_ = {};
	retryAt_ = clock_ + timing_.retry;
	Refill();
	return false;
}

void Cycle::StartFade()
{
	fading_ = true;
	faded_ = 0;
}

void Cycle::Advance(double seconds)
{
	const double step = seconds < 0 ? 0 : seconds > kMostStep ? kMostStep : seconds;
	clock_ += step;
	if (fading_) {
		faded_ += step;
		if (faded_ < timing_.fade) return;
		if (current_.ready) releases_.push_back(current_.entry);
		current_ = next_;
		next_ = {};
		fading_ = stepWanted_ = false;
		faded_ = held_ = 0;
		settleUntil_ = clock_ + timing_.settle;
		Refill();
		return;
	}
	if (current_.ready) held_ += step;
	if (next_.ready && (!current_.ready || held_ >= timing_.hold || stepWanted_)) StartFade();
	Refill();
}

void Cycle::Step()
{
	stepWanted_ = true;
	settleUntil_ = clock_;
	retryAt_ = clock_;
}

void Cycle::Reset()
{
	if (current_.ready) releases_.push_back(current_.entry);
	if (next_.ready) releases_.push_back(next_.entry);
	if (next_.loading) stale_ = next_.entry;
	current_ = next_ = {};
	fading_ = stepWanted_ = false;
	faded_ = held_ = 0;
	Refill();
}

Cycle::Frame Cycle::Shown() const
{
	Frame frame;
	if (current_.ready) frame.under = {current_.entry, 1.f};
	if (fading_ && next_.ready) frame.over = {next_.entry, FadeCurve((float)(faded_ / timing_.fade))};
	return frame;
}

std::vector<int> Cycle::TakeReleases()
{
	std::vector<int> taken;
	taken.swap(releases_);
	return taken;
}

int Cycle::Alive() const
{
	return (current_.ready ? 1 : 0) + (next_.loading || next_.ready ? 1 : 0) + (stale_ >= 0 ? 1 : 0);
}

bool Cycle::Exhausted() const
{
	return entries_ == 0 || failedCount_ >= entries_;
}

} // namespace sfve::backdrop
